--- /dev/null
+++ b/lib/config.js
@@ -0,0 +1,76 @@
+'use strict';
+
+/**
+ * SlugConfig
+ * ----------
+ * Central, extensible configuration object for slug generation.
+ * Every option is validated eagerly so that invalid combinations fail fast.
+ *
+ * @typedef {Object} SlugOptions
+ * @property {boolean} [keepCase=false]        Preserve the original letter case.
+ * @property {string}  [separator='-']        Character used between words.
+ * @property {number}  [maxLength=Infinity]    Truncate the slug to this many characters.
+ * @property {string}  [locale='en']           Locale hint for future locale-aware folding.
+ * @property {boolean} [strict=true]           Remove every non-alphanumeric character.
+ * @property {Object}  [customReplacements={}] Map of substrings to replace before slugging.
+ * @property {boolean} [transliterate=true]    Fold accents to ASCII.
+ * @property {boolean} [lowercaseAfter=false]  Lowercase again after all strategies ran.
+ * @property {boolean} [debug=false]           Log every transformation step.
+ * @property {string}  [caseStrategy='auto']   Which case strategy to resolve from the registry.
+ */
+const DEFAULTS = Object.freeze({
+  keepCase: false,
+  separator: '-',
+  maxLength: Infinity,
+  locale: 'en',
+  strict: true,
+  customReplacements: {},
+  transliterate: true,
+  lowercaseAfter: false,
+  debug: false,
+  caseStrategy: 'auto',
+});
+
+class SlugConfigError extends Error {
+  constructor(message) {
+    super(message);
+    this.name = 'SlugConfigError';
+  }
+}
+
+class SlugConfig {
+  constructor(options = {}) {
+    if (options === null || typeof options !== 'object') {
+      throw new SlugConfigError('options must be an object');
+    }
+    const merged = { ...DEFAULTS, ...options };
+    SlugConfig.validate(merged);
+    Object.assign(this, merged);
+    Object.freeze(this);
+  }
+
+  static validate(o) {
+    const bools = ['keepCase', 'strict', 'transliterate', 'lowercaseAfter', 'debug'];
+    for (const k of bools) {
+      if (typeof o[k] !== 'boolean') throw new SlugConfigError(`${k} must be a boolean`);
+    }
+    if (typeof o.separator !== 'string' || o.separator.length !== 1) {
+      throw new SlugConfigError('separator must be a single character');
+    }
+    if (!(o.maxLength === Infinity || (Number.isInteger(o.maxLength) && o.maxLength > 0))) {
+      throw new SlugConfigError('maxLength must be a positive integer');
+    }
+    if (typeof o.locale !== 'string') throw new SlugConfigError('locale must be a string');
+    if (typeof o.customReplacements !== 'object') {
+      throw new SlugConfigError('customReplacements must be an object');
+    }
+    if (!['auto', 'lower', 'preserve'].includes(o.caseStrategy)) {
+      throw new SlugConfigError('caseStrategy must be auto, lower or preserve');
+    }
+    if (o.keepCase && o.lowercaseAfter) {
+      throw new SlugConfigError('keepCase and lowercaseAfter cannot both be true');
+    }
+  }
+}
+
+module.exports = { SlugConfig, SlugConfigError, DEFAULTS };
