@@ -0,0 +1,33 @@
+'use strict';
+
+/**
+ * StrategyRegistry — a pluggable registry so that future case strategies
+ * (title case, camel case, locale-aware casing) can be added without touching slugify().
+ */
+class StrategyRegistry {
+  constructor() {
+    this._strategies = new Map();
+  }
+
+  register(name, strategy) {
+    if (typeof strategy.apply !== 'function') {
+      throw new TypeError(`strategy ${name} must implement apply(text, config)`);
+    }
+    this._strategies.set(name, strategy);
+    return this;
+  }
+
+  resolve(name) {
+    const s = this._strategies.get(name);
+    if (!s) throw new Error(`unknown strategy: ${name}`);
+    return s;
+  }
+
+  list() {
+    return [...this._strategies.keys()];
+  }
+}
+
+const registry = new StrategyRegistry();
+
+module.exports = { StrategyRegistry, registry };
