 'use strict';

-// Turn a title into a URL slug: "Hello, World!" -> "hello-world".
-function slugify(input) {
-  return String(input)
-    .normalize('NFKD')
-    .replace(/[̀-ͯ]/g, '')
-    .toLowerCase()
