-    .replace(/^-+|-+$/g, '');
+const { SlugConfig } = require('./config');
+const { CaseStrategyFactory } = require('./strategies/factory');
+
+function log(config, step, value) {
+  if (config.debug) console.log(`[slugify] ${step}:`, JSON.stringify(value));
+}
+
+/**
+ * Turn a title into a URL slug: "Hello, World!" -> "hello-world".
+ *
+ * @param {string} input
+ * @param {import('./config').SlugOptions} [options]
+ * @returns {string}
+ */
+function slugify(input, options = {}) {
+  const config = new SlugConfig(options);
+  let text = String(input);
+  log(config, 'input', text);
+
+  for (const [from, to] of Object.entries(config.customReplacements)) {
+    text = text.split(from).join(to);
+  }
+  log(config, 'replacements', text);
+
+  if (config.transliterate) {
+    text = text.normalize('NFKD').replace(/[̀-ͯ]/g, '');
+  }
+  log(config, 'transliterate', text);
+
+  text = CaseStrategyFactory.forConfig(config).apply(text, config);
+  log(config, 'case', text);
+
+  const sep = config.separator;
+  const pattern = config.strict ? /[^A-Za-z0-9]+/g : /\s+/g;
+  text = text.replace(pattern, sep);
+  const edge = new RegExp(`^\\${sep}+|\\${sep}+$`, 'g');
+  text = text.replace(edge, '');
+  log(config, 'separate', text);
+
+  if (config.lowercaseAfter) text = text.toLowerCase();
+  if (text.length > config.maxLength) text = text.slice(0, config.maxLength).replace(edge, '');
+  log(config, 'final', text);
+  return text;
 }

 module.exports = { slugify };
