+'use strict';
+
+const { registry } = require('../registry');
+const { LowercaseStrategy } = require('./lowercase');
+const { PreserveCaseStrategy } = require('./preserve');
+
+registry.register('lower', new LowercaseStrategy());
+registry.register('preserve', new PreserveCaseStrategy());
+
+/**
+ * CaseStrategyFactory picks the case strategy for a given configuration.
+ * 'auto' resolves from keepCase so the two options stay consistent.
+ */
+class CaseStrategyFactory {
+  static forConfig(config) {
+    let name = config.caseStrategy;
+    if (name === 'auto') name = config.keepCase ? 'preserve' : 'lower';
+    return registry.resolve(name);
+  }
+}
+
+module.exports = { CaseStrategyFactory };
